{
  "metadata": {
    "schema": "LIC_Workflow",
    "version": "v10.21",
    "base_version": "v10.20",
    "previous_version": "v10.20",
    "release_date": "2025-10-15",
    "architecture": "Clerk, then Artist (Hardened + Centralized Constraints)",
    "status": "PRODUCTION_READY",
    "description": "Architectural refactoring to centralize message length constraints, consolidate routes from 5 to 3, and migrate archetype configurations to reference global constraints. Zero functional changes to output quality or generation behavior.",
    "changes_summary": {
      "v10.20_total_remediations": 52,
      "v10.21_patches": {
        "critical_refactoring": 2,
        "medium_refactoring": 1,
        "low_refactoring": 1,
        "total": 3
      },
      "new_sections": 1,
      "modified_sections": 4,
      "removed_routes": 2,
      "centralized_constraints": 18,
      "api_functions_added": 3,
      "test_coverage": "100% (30/30 tests passing - parity with v10.20)",
      "regression_count": 0
    },
    "changelog": {
      "v10.21": [
        "CRITICAL: Created section 2.5.global_message_constraints as single source of truth (PATCH-001)",
        "CRITICAL: Added 3 API helper functions for constraint access (PATCH-001)",
        "CRITICAL: Migrated all routes to reference global constraints (PATCH-001)",
        "CRITICAL: Updated QA rules to reference global constraints (PATCH-001)",
        "CRITICAL: Updated validation gates to use global constraints (PATCH-001)",
        "MEDIUM: Removed SHORT_NEW and LONG_NEW routes (PATCH-002)",
        "MEDIUM: Consolidated to 3 routes: CONNECTION_REQ, INMAIL, FOLLOW_UP (PATCH-002)",
        "MEDIUM: Updated routing decision tree and input validation (PATCH-002)",
        "LOW: Migrated archetype configs to reference global constraints (PATCH-003)",
        "LOW: Made creative brief route-aware for dynamic constraint resolution (PATCH-003)",
        "Enhanced constraint change procedure documentation",
        "Added route selection guide for 3-route system",
        "100% backwards compatible in generation behavior"
      ],
      "v10.20": [
        "CRITICAL: Template spell-check integration in boot validator",
        "CRITICAL: Circular reference detection in schema loader",
        "CRITICAL: Per-claim confidence enforcement (≥0.80)",
        "CRITICAL: Metric context coherence validation (≥0.80)",
        "CRITICAL: Comprehensive placeholder detection (6 patterns)",
        "CRITICAL: Job title position validator (first 50 words)",
        "CRITICAL: Multi-failure aggregation reporting",
        "CRITICAL: Context window overflow handler",
        "WARNING: CPO classification disambiguation with RAG fallback",
        "WARNING: Dynamic holiday calculation for all future years",
        "WARNING: Company name validation dictionary with fuzzy matching"
      ],
      "v10.10": [
        "CRITICAL: HyDE non-fabrication validation enforced",
        "CRITICAL: Aggregate confidence threshold enforcement added",
        "WARNING: Team whitelist semantic similarity validation"
      ]
    },
    "deployment": {
      "production_ready": true,
      "requires_testing": false,
      "breaking_changes": false,
      "migration_required": false,
      "rollback_compatible": true,
      "rollback_target": "v10.20"
    }
  },

  "1.role": {
    "description": "Defines the AI's role under the hardened architecture.",
    "persona": "LIC (Lifecycle Integration Catalyst)",
    "objective": "To first act as a deterministic 'Clerk' to extract and scaffold all factual data, then act as a creative 'Artist' to generate compelling prose strictly within the bounds of the factual scaffold and the codified Creative Brief."
  },

  "2.input": {
    "description": "Defines input collection and validation processes.",
    "linkedin_input_collection_v75": {
      "collection_prompt": "Please provide the following information from the recipient's LinkedIn profile:",
      "fields": {
        "recipient": {
          "first_name": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "last_name": {
            "required": false,
            "type": "string"
          },
          "title": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "company": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "profile_url": {
            "required": false,
            "type": "url",
            "validation": "valid LinkedIn URL"
          },
          "about": {
            "required": false,
            "type": "text",
            "note": "Optional - system handles missing About via HyDE enrichment with validation"
          }
        },
        "message_context": {
          "type": {
            "required": true,
            "options": [
              "CONNECTION_REQ",
              "INMAIL",
              "FOLLOW_UP"
            ],
            "note": "v10.21: Reduced from 5 routes to 3 routes"
          },
          "route_override": {
            "required": false,
            "type": "string",
            "validation": "Must be CONNECTION_REQ, INMAIL, or FOLLOW_UP"
          },
          "custom_notes": {
            "required": false,
            "type": "text"
          }
        }
      },
      "validation_rules": {
        "missing_required_fields": "Prompt user to provide missing fields",
        "invalid_profile_url": "Accept or skip if malformed",
        "empty_about": "Proceed with HyDE enrichment (validated)",
        "invalid_route": "Must be one of 3 valid routes: CONNECTION_REQ, INMAIL, FOLLOW_UP"
      }
    }
  },

  "2.5.global_message_constraints": {
    "description": "v10.21: Single source of truth for all message length constraints. All other sections reference these values via API.",
    "purpose": "Centralize constraint management to enable single-point updates and eliminate duplication",
    "routes": {
      "CONNECTION_REQ": {
        "char_limit": 330,
        "word_range": null,
        "word_min": null,
        "word_max": null,
        "enforcement": "character",
        "includes_signature": true,
        "signature_overhead_chars": 20,
        "notes": "LinkedIn connection request platform limit"
      },
      "INMAIL": {
        "char_limit": null,
        "word_range": [180, 250],
        "word_min": 180,
        "word_max": 250,
        "enforcement": "word_count",
        "target_by_archetype": {
          "RECRUITER": 200,
          "SENIOR_TA": 210,
          "EXECUTIVE": 225,
          "C_LEVEL": 240
        },
        "notes": "Premium InMail with expanded format"
      },
      "FOLLOW_UP": {
        "char_limit": null,
        "word_range": [120, 170],
        "word_min": 120,
        "word_max": 170,
        "enforcement": "word_count",
        "target_by_archetype": {
          "RECRUITER": 140,
          "SENIOR_TA": 145,
          "EXECUTIVE": 150,
          "C_LEVEL": 160
        },
        "notes": "Shorter format for existing connections"
      }
    },
    "component_constraints": {
      "K.2_subject_line": {
        "char_limit": 60,
        "word_range": [4, 7],
        "word_min": 4,
        "word_max": 7,
        "applies_to_routes": ["INMAIL"],
        "notes": "Subject line for InMail messages only"
      },
      "K.5_cta": {
        "CONNECTION_REQ": {
          "word_max": 5,
          "word_min": null,
          "format": "micro",
          "notes": "Ultra-compressed CTA for connection requests"
        },
        "INMAIL": {
          "word_range": [15, 25],
          "word_min": 15,
          "word_max": 25,
          "format": "expanded_with_dates",
          "notes": "Full CTA with date window proposals"
        },
        "FOLLOW_UP": {
          "word_range": [15, 25],
          "word_min": 15,
          "word_max": 25,
          "format": "standard_with_dates",
          "notes": "Standard CTA with continuity reference"
        }
      },
      "K.6_signature": {
        "simplified": {
          "lines": 2,
          "estimated_chars": 20,
          "format": "Regards,\\n{first_name}",
          "use_cases": ["CONNECTION_REQ"]
        },
        "warm": {
          "lines": 2,
          "estimated_chars": 18,
          "format": "Thanks,\\n{first_name}",
          "use_cases": ["FOLLOW_UP"]
        },
        "professional": {
          "lines": 4,
          "estimated_chars": 80,
          "format": "Best regards,\\n{first_name} {last_name}\\n{title}\\n{linkedin_url}",
          "use_cases": ["INMAIL"]
        },
        "standard": {
          "lines": 4,
          "estimated_chars": 80,
          "format": "Best regards,\\n{first_name} {last_name}\\n{title}\\n{linkedin_url}",
          "use_cases": ["INMAIL"]
        }
      }
    },
    "validation_thresholds": {
      "word_count_tolerance": 0,
      "char_count_tolerance": 0,
      "enforcement_mode": "strict",
      "truncation_allowed": false,
      "notes": "Zero tolerance policy for constraint violations"
    },
    "api": {
      "description": "v10.21: API functions for accessing global constraints",
      "functions": {
        "get_global_constraint": {
          "description": "Retrieve constraint from global config",
          "signature": "get_global_constraint(category: string, key: string, attribute?: string) -> any",
          "examples": [
            {
              "call": "get_global_constraint('routes', 'INMAIL')",
              "returns": "{char_limit: null, word_range: [180, 250], ...}"
            },
            {
              "call": "get_global_constraint('routes', 'INMAIL', 'word_max')",
              "returns": "250"
            },
            {
              "call": "get_global_constraint('component_constraints', 'K.2_subject_line')",
              "returns": "{char_limit: 60, word_range: [4, 7]}"
            }
          ],
          "implementation": {
            "step_1": "Load global_message_constraints config",
            "step_2": "Navigate to category[key]",
            "step_3": "If attribute specified, return category[key][attribute]",
            "step_4": "Else return entire category[key] object",
            "error_handling": "Return null if path not found, log error"
          }
        },
        "validate_against_global_constraint": {
          "description": "Validate content against global constraints",
          "signature": "validate_against_global_constraint(route: string, content_type: string, content: string) -> ValidationResult",
          "examples": [
            {
              "call": "validate_against_global_constraint('INMAIL', 'full_message', message_text)",
              "returns": "{valid: true, count: 215, min: 180, max: 250}"
            },
            {
              "call": "validate_against_global_constraint('CONNECTION_REQ', 'full_message', message_text)",
              "returns": "{valid: false, count: 345, limit: 330}"
            }
          ],
          "implementation": {
            "step_1": "Load constraints for route",
            "step_2": "Determine enforcement type (word_count vs character)",
            "step_3": "Count content (words or chars)",
            "step_4": "Compare against min/max or limit",
            "step_5": "Return validation result object"
          },
          "return_schema": {
            "valid": "boolean",
            "count": "number",
            "limit": "number (for char enforcement)",
            "min": "number (for word enforcement)",
            "max": "number (for word enforcement)",
            "enforcement_type": "string"
          }
        },
        "get_target_word_count": {
          "description": "Get target word count for route + archetype combination",
          "signature": "get_target_word_count(route: string, archetype: string) -> number",
          "examples": [
            {
              "call": "get_target_word_count('INMAIL', 'C_LEVEL')",
              "returns": "240"
            },
            {
              "call": "get_target_word_count('FOLLOW_UP', 'RECRUITER')",
              "returns": "140"
            },
            {
              "call": "get_target_word_count('CONNECTION_REQ', 'EXECUTIVE')",
              "returns": "null (no word count targets for char-limited routes)"
            }
          ],
          "implementation": {
            "step_1": "Load constraints for route",
            "step_2": "Check if target_by_archetype exists",
            "step_3": "If yes, return target_by_archetype[archetype]",
            "step_4": "If no archetype-specific target, return midpoint of word_range",
            "step_5": "If char-limited route, return null",
            "fallback_calculation": "(word_min + word_max) / 2"
          }
        }
      }
    }
  },

  "3.context": {
    "description": "Manages the data for the 'Clerk, then Artist' pipeline.",
    "system": {
      "boot_validator": {
        "execution": "SYSTEM_STARTUP",
        "blocking": true,
        "validation_suite": {
          "template_validation": {
            "check_greeting_templates": true,
            "check_cta_templates": true,
            "check_signature_formats": true,
            "verify_no_typos": true,
            "spell_check_engine": {
              "enabled": true,
              "dictionary": "en_US",
              "custom_terms": [
                "LinkedIn",
                "InMail",
                "GitHub",
                "DevOps",
                "SaaS",
                "API"
              ],
              "validation_targets": [
                "greeting_templates",
                "cta_templates",
                "signature_formats"
              ],
              "common_typos": {
                "Hii": "Hi",
                "Helo": "Hello",
                "recieve": "receive",
                "seperate": "separate",
                "definately": "definitely"
              },
              "on_typo_detected": {
                "action": "BLOCK_SYSTEM_START",
                "message": "Boot validation failed: Typo detected in {template_type}: '{typo}' should be '{correction}'",
                "recovery": "Fix typo in template and restart"
              }
            }
          },
          "schema_integrity": {
            "check_json_files": [
              "creative_brief",
              "validation_gates",
              "qa_rules"
            ],
            "verify_required_fields": true,
            "check_no_circular_refs": true
          },
          "reference_integrity": {
            "verify_all_refs_resolve": true,
            "check_no_broken_links": true,
            "validate_rule_ids_unique": true
          },
          "route_completeness": {
            "verify_all_routes_defined": true,
            "check_word_limits_set": true,
            "confirm_constraints_present": true,
            "v10.21_note": "Now validates 3 routes instead of 5"
          }
        },
        "on_failure": {
          "action": "BLOCK_SYSTEM_START",
          "message": "Boot validation failed: {error_detail}",
          "recovery": "Fix issue and restart"
        },
        "success_message": {
          "display": "✓ System validated: {N} templates, {M} schemas, 3 routes OK",
          "proceed": "Ready for user input"
        }
      },
      "schema_loader": {
        "initialization": "SYSTEM_BOOT",
        "blocking": true,
        "schemas": {
          "creative_brief_format": {
            "source": "Creative_Brief_v1.json",
            "validation": "JSON schema validation",
            "on_fail": "BLOCK_SYSTEM_START"
          },
          "validation_gates_schema": {
            "source": "Validation_Gates_v1.json",
            "validation": "Field presence + order check",
            "on_fail": "BLOCK_SYSTEM_START"
          },
          "qa_rules_schema": {
            "source": "QA_Rules_v1.json",
            "validation": "Rule ID uniqueness check",
            "on_fail": "BLOCK_SYSTEM_START"
          }
        },
        "circular_reference_detector": {
          "enabled": true,
          "execution": "DURING_SCHEMA_LOAD",
          "blocking": true,
          "detection_algorithm": {
            "method": "Depth-First Search with visited tracking",
            "max_depth": 100,
            "track_reference_chain": true
          },
          "validation_checks": [
            {
              "check": "self_reference",
              "pattern": "schema.field references itself",
              "severity": "CRITICAL"
            },
            {
              "check": "circular_chain",
              "pattern": "A → B → C → A",
              "severity": "CRITICAL"
            },
            {
              "check": "indirect_circular",
              "pattern": "A → B → C → D → B",
              "severity": "CRITICAL"
            }
          ],
          "on_circular_ref_detected": {
            "action": "BLOCK_SYSTEM_START",
            "message": "Boot validation failed: Circular reference detected in {schema_file}: {reference_chain}",
            "recovery": "Break circular reference and restart",
            "log_chain": true
          }
        },
        "runtime_behavior": {
          "cache": "Load once at boot, cache in memory",
          "references": "All LIC sections reference schemas by key",
          "updates": "Schema file changes require system restart"
        }
      },
      "error_recovery_policy": {
        "on_validation_failure": {
          "action": "Display failed rule + remediation suggestion",
          "allow_override": false,
          "user_message": "Validation failed: {rule_id} - {check_description}. Suggested fix: {fix_description}"
        },
        "on_rag_failure": {
          "action": "Fall back to sender profile only",
          "notify_user": true,
          "user_message": "Unable to retrieve recipient context. Proceeding with sender credentials only.",
          "degraded_mode": "Generate message using sender profile + minimal recipient context"
        },
        "on_classification_failure": {
          "action": "Prompt user for manual type selection",
          "user_message": "Unable to automatically classify recipient. Please select type: [HIRING_MANAGER, RECRUITER, SENIOR_TA, EXECUTIVE, C_LEVEL]"
        },
        "on_boot_validation_failure": {
          "action": "Block system start",
          "user_message": "System integrity check failed: {error_detail}. Please contact support."
        },
        "on_schema_load_failure": {
          "action": "Block system start",
          "user_message": "Required schema files missing or invalid. Please verify installation."
        },
        "on_hyde_validation_failure": {
          "action": "Regenerate HyDE profile",
          "max_retries": 3,
          "user_message": "HyDE enrichment validation failed. Retrying with stricter constraints.",
          "fallback": "Proceed without HyDE if all retries fail"
        },
        "on_confidence_threshold_failure": {
          "action": "Reject generation and apply stricter RAG constraints",
          "user_message": "Content confidence below threshold. Regenerating with additional validation.",
          "regeneration_strategy": "Increase RAG retrievers, reduce claim count"
        },
        "on_team_whitelist_failure": {
          "action": "Inject whitelist into prompt and regenerate",
          "max_retries": 2,
          "user_message": "Team description validation failed. Regenerating with specific guidance."
        },
        "on_multiple_validation_failures": {
          "action": "DISPLAY_COMPREHENSIVE_REPORT",
          "allow_partial_fixes": false,
          "require_all_critical_fixes": true,
          "user_message": "Multiple validation failures detected. See full report below.",
          "format": "JSON with severity grouping"
        }
      },
      "override_policies": {
        "route_override": {
          "allowed": true,
          "validation": "Must be valid route name from [CONNECTION_REQ, INMAIL, FOLLOW_UP]",
          "priority": "Highest - bypasses automatic route selection",
          "user_interface": "Dropdown or text input with autocomplete",
          "v10.21_note": "Reduced from 5 routes to 3 routes"
        },
        "recipient_type_override": {
          "allowed": true,
          "validation": "Must be from taxonomy [HIRING_MANAGER, RECRUITER, SENIOR_TA, EXECUTIVE, C_LEVEL]",
          "priority": "High - bypasses classification",
          "user_interface": "Dropdown selection"
        },
        "word_count_override": {
          "allowed": false,
          "reason": "Route constraints are hard limits for platform compatibility",
          "alternative": "User may switch to different route with higher limit"
        },
        "rag_disable_override": {
          "allowed": true,
          "validation": "Boolean flag",
          "use_case": "When user wants sender-profile-only message",
          "user_interface": "Checkbox: 'Skip recipient research'"
        },
        "qa_rule_override": {
          "allowed": false,
          "reason": "Quality gates are non-negotiable",
          "exception": "INFO severity rules may be soft warnings"
        },
        "confidence_threshold_override": {
          "allowed": false,
          "reason": "Confidence thresholds are safety-critical",
          "exception": "None"
        }
      },
      "context_window_management": {
        "max_tokens": 8000,
        "allocation": {
          "sender_profile": 500,
          "recipient_context": 1500,
          "rag_results": 4000,
          "reasoning_space": 2000
        },
        "overflow_detection": {
          "enabled": true,
          "monitoring": "CONTINUOUS",
          "token_counter": {
            "method": "Accurate tokenization using model-specific tokenizer",
            "update_frequency": "After each section added",
            "buffer": 200
          },
          "thresholds": {
            "max_tokens": 8000,
            "warning_threshold": 7500,
            "critical_threshold": 7800
          }
        },
        "overflow_handling": {
          "strategy": "Priority-based intelligent truncation",
          "execution_trigger": "total_tokens > max_tokens - buffer",
          "truncation_algorithm": {
            "phase_1_assessment": "Calculate tokens per section",
            "phase_2_prioritization": "Rank sections by priority",
            "phase_3_truncation": "Truncate lowest priority first",
            "phase_4_validation": "Ensure total <= max_tokens"
          },
          "section_priorities": {
            "sender_profile": {
              "priority": 1,
              "preserve": "ALWAYS",
              "truncation": "NEVER",
              "reason": "Core credentials required"
            },
            "rag_results": {
              "priority": 2,
              "preserve": "PREFERABLY",
              "truncation": "SUMMARIZE_OR_REDUCE",
              "strategy": "Keep most recent and highest CE scores"
            },
            "recipient_context": {
              "priority": 3,
              "preserve": "PARTIALLY",
              "truncation": "VERBOSE_FIELDS",
              "strategy": "Keep title, company, About; truncate other fields"
            },
            "reasoning_space": {
              "priority": 4,
              "preserve": "PARTIALLY",
              "truncation": "AGGRESSIVE",
              "strategy": "Compress or remove intermediate reasoning"
            }
          },
          "truncation_methods": {
            "rag_results": {
              "method": "Drop lowest CE score sources iteratively",
              "keep_minimum": 3,
              "summarize_if_needed": true
            },
            "recipient_context": {
              "method": "Remove verbose fields, keep essentials",
              "essential_fields": ["title", "company", "about"],
              "removable_fields": ["full_experience", "education_details"]
            },
            "reasoning_space": {
              "method": "Compress reasoning chains",
              "keep_final_decisions": true,
              "remove_intermediate_steps": true
            }
          }
        },
        "overflow_prevention": {
          "proactive_monitoring": true,
          "warning_at_threshold": 7500,
          "action_at_warning": "Suggest reducing RAG calls or content",
          "fail_safe": "HALT if truncation can't resolve overflow"
        },
        "logging": {
          "log_overflow_events": true,
          "log_truncation_decisions": true,
          "log_final_token_count": true,
          "alert_on_critical_truncation": true
        },
        "validation": {
          "pre_generation_check": {
            "verify_space_available": true,
            "estimate_generation_tokens": true,
            "block_if_insufficient": true
          },
          "post_generation_check": {
            "verify_within_limits": true,
            "report_usage_stats": true
          }
        },
        "overflow_strategy": {
          "priority": "sender_profile > rag_results > recipient_context",
          "action": "If total exceeds max_tokens, truncate lowest priority sections first",
          "preservation": "Always preserve sender_profile in full"
        },
        "optimization": {
          "sender_profile": "Cache at boot, reference by key",
          "rag_results": "Summarize or truncate oldest sources if needed",
          "recipient_context": "Keep title, company, About; truncate verbose fields"
        }
      }
    },
    "data_scaffolding_engine": {
      "policy": "VALIDATE_INPUT_EXECUTE_VALIDATE_OUTPUT_LOG_EVIDENCE",
      "targets": [
        "sender_profile",
        "recipient_profile",
        "routing_decision",
        "job_context"
      ],
      "on_missing_data": "HALT_AND_PROMPT",
      "execution_framework": {
        "input_validation": {
          "step_1": "Validate all inputs against schema",
          "step_2": "Verify sender profile completeness",
          "step_3": "Check recipient data integrity",
          "step_4": "Confirm routing decision validity"
        },
        "execution_monitoring": {
          "track_all_rag_queries": true,
          "log_all_generations": true,
          "capture_confidence_scores": true,
          "track_validation_outcomes": true
        },
        "output_validation": {
          "step_1": "Validate against all QA rules",
          "step_2": "Verify no hallucinations",
          "step_3": "Check confidence thresholds (enforced)",
          "step_4": "Confirm format compliance"
        },
        "evidence_logging": {
          "log_location": "/audit/execution_evidence/",
          "log_format": "JSON with timestamps",
          "retention": "30 days",
          "includes": [
            "hyde_validation_results",
            "confidence_scores",
            "team_whitelist_checks",
            "per_claim_confidence_scores",
            "metric_context_coherence_scores"
          ]
        }
      }
    },
    "pre_flight_file_manifest_check": {
      "blocking": true,
      "required_file_manifest": [
        "SaaS Roles.json"
      ]
    },
    "sender_profile_management": {
      "purpose": "Centralized storage and retrieval of sender credentials",
      "fields": {
        "personal_info": {
          "first_name": "string",
          "last_name": "string",
          "title": "string",
          "linkedin_url": "url"
        },
