  "7.pipeline": {
    "description": "Defines the three-phase pipeline for generating LinkedIn outreach. v10.21 uses global constraints throughout.",
    "phases": [
      {
        "phase": 1,
        "name": "The Clerk: Deterministic Data Scaffolding",
        "engine": "Deterministic Extraction Engine",
        "description": "Programmatically extracts all factual data from user inputs (recipient profile, routing decisions) and required files."
      },
      {
        "phase": 2,
        "name": "The Artist: Grounded Generation",
        "engine": "Grounded Generation Engine",
        "description": "The creative LLM is invoked for all generative tasks (subject, body, CTA), governed by the rules in the 'creative_brief'. Uses route-aware constraint resolution.",
        "v10.21_enhancement": "Now uses get_target_word_count(route, archetype) for dynamic constraint resolution"
      },
      {
        "phase": 3,
        "name": "The Assembler: Final Rendering & Validation",
        "engine": "Deterministic Assembly Engine",
        "description": "Programmatically combines the factual scaffold with the creative prose and runs all final validation gates before rendering the final message. All length validation uses global constraints.",
        "v10.21_enhancement": "All constraint validation now references 2.5.global_message_constraints"
      }
    ],
    "pipeline_enhancements": {
      "interactive_pauses": {
        "after_clerk_phase": {
          "display": "Data scaffold complete",
          "user_review": true,
          "allow_override": true
        },
        "after_artist_phase": {
          "display": "Creative generation complete",
          "show_confidence_scores": true,
          "show_per_claim_scores": true,
          "allow_regeneration": true
        },
        "after_validation": {
          "display": "QA validation results",
          "show_violations": true,
          "show_all_failures": true,
          "require_confirmation": true
        }
      },
      "execution_tracking": {
        "log_all_phases": true,
        "capture_timing_metrics": true,
        "track_retry_attempts": true,
        "save_execution_history": true
      },
      "error_recovery": {
        "recoverable_errors": [
          "Low confidence score",
          "Missing optional field",
          "RAG timeout",
          "HyDE validation failure",
          "Team whitelist mismatch",
          "Single low-confidence claim",
          "Company name misspelling"
        ],
        "max_retries": 3,
        "retry_strategy": "Exponential backoff",
        "blocking_errors": [
          "Missing required field",
          "Critical QA failure",
          "Hallucination detected",
          "Aggregate confidence below 0.95",
          "Per-claim confidence below 0.80",
          "HyDE fabrication detected",
          "Placeholder detected",
          "Job title position invalid",
          "Metric context coherence below 0.80"
        ]
      }
    }
  },

